 #[cfg(target_os = "android")]
 struct Renderer {
     _instance: wgpu::Instance,
     window: Arc<Window>,
     surface: wgpu::Surface<'static>,
     adapter: wgpu::Adapter,
     device: wgpu::Device,
     queue: wgpu::Queue,
     config: wgpu::SurfaceConfiguration,
     presented: u64,
 }

 #[cfg(target_os = "android")]
 impl Renderer {
     fn new(window: Arc<Window>) -> Result<Self, String> {
         #[cfg(feature = "probe-vulkan")]
         let backend = wgpu::Backends::VULKAN;
         #[cfg(feature = "probe-gles")]
         let backend = wgpu::Backends::GL;

         let mut descriptor = wgpu::InstanceDescriptor::new_without_display_handle();
         descriptor.backends = backend;
         let instance = wgpu::Instance::new(descriptor);
         let surface = instance
             .create_surface(window.clone())
             .map_err(|error| format!("surface creation failed: {error}"))?;

         let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
             power_preference: wgpu::PowerPreference::HighPerformance,
             compatible_surface: Some(&surface),
             force_fallback_adapter: false,
             ..Default::default()
         }))
         .map_err(|error| format!("adapter request failed: {error}"))?;
         let info = adapter.get_info();
         log::info!(
             "ADAPTER backend={:?} name={} device_type={:?} driver={} driver_info={}",
             info.backend,
             info.name,
             info.device_type,
             info.driver,
             info.driver_info
         );

         let (device, queue) =
             pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
                 .map_err(|error| format!("device request failed: {error}"))?;

         let capabilities = surface.get_capabilities(&adapter);
         let format = capabilities
             .formats
             .first()
             .copied()
             .ok_or("surface exposes no formats")?;
         let present_mode = if capabilities
             .present_modes
             .contains(&wgpu::PresentMode::Fifo)
         {
             wgpu::PresentMode::Fifo
         } else {
             *capabilities
                 .present_modes
                 .first()
                 .ok_or("surface exposes no present modes")?
         };
         let alpha_mode = *capabilities
             .alpha_modes
             .first()
             .ok_or("surface exposes no alpha modes")?;
         let size = window.inner_size();
         let config = wgpu::SurfaceConfiguration {
             usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
             format,
             width: size.width.max(1),
             height: size.height.max(1),
             present_mode,
             desired_maximum_frame_latency: 2,
             alpha_mode,
             view_formats: vec![],
             color_space: wgpu::SurfaceColorSpace::default(),
         };
         surface.configure(&device, &config);
         log::info!(
             "SURFACE configured width={} height={} format={:?} present_mode={:?}",
             config.width,
             config.height,
             config.format,
             config.present_mode
         );

         Ok(Self {
             _instance: instance,
             window,
             surface,
             adapter,
             device,
             queue,
             config,
             presented: 0,
         })
     }

     fn resize(&mut self, width: u32, height: u32) {
         if width == 0 || height == 0 {
             return;
         }
         self.config.width = width;
         self.config.height = height;
         self.surface.configure(&self.device, &self.config);
         log::info!("SURFACE resized width={width} height={height}");
         self.window.request_redraw();
     }

