 #[cfg(target_os = "android")]
 #[derive(Default)]
 struct App {
     renderer: Option<Renderer>,
 }

 #[cfg(target_os = "android")]
 impl ApplicationHandler for App {
     fn resumed(&mut self, event_loop: &ActiveEventLoop) {
         log::info!("LIFECYCLE resumed");
         if self.renderer.is_some() {
             return;
         }
         let window = match event_loop
             .create_window(Window::default_attributes().with_title("Horizon Android Render Probe"))
         {
             Ok(window) => Arc::new(window),
             Err(error) => {
                 log::error!("WINDOW creation failed: {error}");
                 event_loop.exit();
                 return;
             }
         };
         match Renderer::new(window) {
             Ok(renderer) => {
                 renderer.window.request_redraw();
                 self.renderer = Some(renderer);
             }
             Err(error) => {
                 log::error!("RENDERER initialization failed: {error}");
                 event_loop.exit();
             }
         }
     }

     fn suspended(&mut self, _event_loop: &ActiveEventLoop) {
         log::info!("LIFECYCLE suspended; releasing surface and device");
         self.renderer = None;
     }

     fn window_event(
         &mut self,
         event_loop: &ActiveEventLoop,
         _window_id: WindowId,
         event: WindowEvent,
     ) {
         match event {
             WindowEvent::CloseRequested => event_loop.exit(),
             WindowEvent::Resized(size) => {
                 if let Some(renderer) = &mut self.renderer {
                     renderer.resize(size.width, size.height);
                 }
             }
             WindowEvent::RedrawRequested => {
                 if let Some(renderer) = &mut self.renderer {
                     if let Err(error) = renderer.draw() {
                         log::error!("RENDER failed: {error}");
                         event_loop.exit();
                     }
                 }
             }
             _ => {}
         }
     }
 }

 #[cfg(target_os = "android")]
 #[no_mangle]
 pub fn android_main(app: AndroidApp) {
     android_logger::init_once(
         android_logger::Config::default()
             .with_tag("HorizonRenderProbe")
             .with_max_level(log::LevelFilter::Info),
     );
     log::info!("START android render probe");
     let mut builder = EventLoop::builder();
     builder.with_android_app(app);
     builder
         .build()
         .and_then(|event_loop| {
             event_loop.set_control_flow(ControlFlow::Wait);
             event_loop.run_app(&mut App::default())
         })
