 #[cfg(target_os = "android")]
 use std::sync::Arc;

 #[cfg(target_os = "android")]
 use winit::{
     application::ApplicationHandler,
     event::WindowEvent,
     event_loop::{ActiveEventLoop, ControlFlow, EventLoop},
     platform::android::{activity::AndroidApp, EventLoopBuilderExtAndroid},
     window::{Window, WindowId},
