         name: info.name.clone(),
         vendor: horizon_telemetry::system::gpu_vendor(&info.name, info.vendor).to_owned(),
         kind: crate::telemetry::gpu_kind(&format!("{:?}", info.device_type)).to_owned(),
         driver: format!("{} {}", info.driver, info.driver_info)
             .trim()
             .to_owned(),
