     };
     let resources = loaded.resources;
     let game = start_game(
         &resources,
         loaded.pack,
         gui,
         options,
         loaded.pack_error.or(pack_error),
         audio,
         vanilla_root,
         started,
         loaded.rest_loader,
         None,
         None,
     )?;
     if let Some(game) = game {
         run_event_loop(game)?;
     }
     Ok(())
 }

