 /// macOS, Ctrl elsewhere) and neither Shift nor Alt.
 pub fn edit_shortcut(
     letter: Option<char>,
     edit_modifier: bool,
     shift: bool,
     alt: bool,
 ) -> Option<EditShortcut> {
     if !edit_modifier || shift || alt {
         return None;
     }
     Some(match letter? {
         'a' => EditShortcut::SelectAll,
         'c' => EditShortcut::Copy,
         'v' => EditShortcut::Paste,
         'x' => EditShortcut::Cut,
         _ => return None,
     })
 }

