 use jni::{
     JavaVM,
     objects::{JObject, JString, JValue},
 };
 use ndk_context::android_context;

 fn with_clipboard<T>(
     operation: impl FnOnce(&mut jni::JNIEnv<'_>, &JObject<'_>, &JObject<'_>) -> jni::errors::Result<T>,
 ) -> Result<T, String> {
     let context = android_context();
     let vm = unsafe { JavaVM::from_raw(context.vm().cast()) }
         .map_err(|error| format!("attach to Android VM: {error}"))?;
     let mut env = vm
         .attach_current_thread()
         .map_err(|error| format!("attach Android clipboard thread: {error}"))?;
     let context = unsafe { JObject::from_raw(context.context().cast()) };
     let service_name = env
         .new_string("clipboard")
         .map_err(|error| format!("create clipboard service name: {error}"))?;
     let service_name = JObject::from(service_name);
     let manager = env
         .call_method(
             &context,
             "getSystemService",
             "(Ljava/lang/String;)Ljava/lang/Object;",
             &[JValue::Object(&service_name)],
         )
         .and_then(|value| value.l())
         .map_err(|error| format!("get Android ClipboardManager: {error}"))?;
     operation(&mut env, &context, &manager).map_err(|error| error.to_string())
 }

 pub(super) fn get_text() -> Result<Option<String>, String> {
     with_clipboard(|env, context, manager| {
         let clip = env
             .call_method(manager, "getPrimaryClip", "()Landroid/content/ClipData;", &[])?
             .l()?;
         if clip.is_null()
             || env
                 .call_method(&clip, "getItemCount", "()I", &[])?
                 .i()?
                 == 0
         {
             return Ok(None);
         }
         let item = env
             .call_method(
                 &clip,
                 "getItemAt",
                 "(I)Landroid/content/ClipData$Item;",
                 &[JValue::Int(0)],
             )?
             .l()?;
         let text = env
             .call_method(
                 &item,
                 "coerceToText",
                 "(Landroid/content/Context;)Ljava/lang/CharSequence;",
                 &[JValue::Object(context)],
             )?
             .l()?;
         if text.is_null() {
             return Ok(None);
         }
         let value = env
             .call_method(&text, "toString", "()Ljava/lang/String;", &[])?
             .l()?;
         let value = JString::from(value);
         let value: String = env.get_string(&value)?.into();
         Ok(Some(value))
     })
 }

 pub(super) fn set_text(text: &str) -> Result<(), String> {
     with_clipboard(|env, _context, manager| {
         let label = JObject::from(env.new_string("Horizon")?);
         let text = JObject::from(env.new_string(text)?);
         let clip = env
             .call_static_method(
                 "android/content/ClipData",
                 "newPlainText",
                 "(Ljava/lang/CharSequence;Ljava/lang/CharSequence;)Landroid/content/ClipData;",
                 &[JValue::Object(&label), JValue::Object(&text)],
             )?
             .l()?;
         env.call_method(
             manager,
             "setPrimaryClip",
             "(Landroid/content/ClipData;)V",
             &[JValue::Object(&clip)],
         )?;
         Ok(())
     })
 }

