     fn pad_show(&mut self) {
         if self.pad.devices.output.is_none() {
             return;
         }
         let playing = self.pad.devices.dualsense
             && self.focused
             && self.title.is_none()
             && self.screen == Screen::Playing
             && !self.pause;
         let (using, attacking) = if playing {
             self.trigger_feels()
         } else {
             (TriggerFeel::Free, TriggerFeel::Free)
         };
