 //! | winit |       ndk-glue               |
 //! | :---: | :--------------------------: |
 //! | 0.30  | `android-activity = "0.6"`   |
 //! | 0.29  | `android-activity = "0.5"`   |
 //! | 0.28  | `android-activity = "0.4"`   |
 //! | 0.27  | `ndk-glue = "0.7"`           |
 //! | 0.26  | `ndk-glue = "0.5"`           |
 //! | 0.25  | `ndk-glue = "0.3"`           |
 //! | 0.24  | `ndk-glue = "0.2"`           |
