 fn draw_pixel_text(batch: &mut HudBatch, atlas: &HudAtlas, text: &str, x: f32, y: f32, scale: f32) {
     let color = rgba(238, 241, 250, 255);
     for (index, ch) in text.chars().enumerate() {
         let rows = pixel_glyph_rows(ch);
         for (row, bits) in rows.into_iter().enumerate() {
             for col in 0..5 {
                 if bits & (1 << (4 - col)) != 0 {
                     batch.fill(
                         atlas,
                         x + (index as f32 * 6.0 + col as f32) * scale,
                         y + row as f32 * scale,
                         scale,
                         scale,
                         color,
                     );
                 }
             }
         }
     }
 }

 fn draw_resource_error(batch: &mut HudBatch, atlas: &HudAtlas) {
     let scale = (batch.height / 360.0).floor().max(1.0);
     let lines = [
         "HORIZON",
         "JAVA RESOURCES NOT FOUND",
         "PREPARE YOUR FILES ON A PC WITH",
         "HORIZON-PREPARE --PREPARE",
         "COPY THE OUTPUT INTO:",
         "ANDROID/DATA/DEV.PLAYHORIZON.HORIZON.CLIENT/FILES/RESOURCES/26.3",
         "RESTART HORIZON AFTER COPYING",
         "DETAILS ARE IN ANDROID/README.MD",
     ];
     let panel_width = batch.width * 0.9;
     let panel_height = (lines.len() as f32 * 16.0 * scale + 32.0).min(batch.height * 0.9);
     let panel_x = (batch.width - panel_width) / 2.0;
     let panel_y = (batch.height - panel_height) / 2.0;
     batch.fill(atlas, 0.0, 0.0, batch.width, batch.height, rgba(10, 13, 22, 255));
     batch.fill(atlas, panel_x, panel_y, panel_width, panel_height, rgba(25, 31, 48, 255));
     for (index, line) in lines.iter().enumerate() {
         let text_width = line.len() as f32 * 6.0 * scale;
         let x = (batch.width - text_width) / 2.0;
         let y = panel_y + 16.0 * scale + index as f32 * 16.0 * scale;
         draw_pixel_text(batch, atlas, line, x, y, scale);
     }
 }

