 fn pixel_glyph_rows(ch: char) -> [u8; 7] {
     match ch {
         'A' => [14, 17, 17, 31, 17, 17, 17],
         'B' => [30, 17, 17, 30, 17, 17, 30],
         'C' => [14, 17, 16, 16, 16, 17, 14],
         'D' => [30, 17, 17, 17, 17, 17, 30],
         'E' => [31, 16, 16, 30, 16, 16, 31],
         'F' => [31, 16, 16, 30, 16, 16, 16],
         'G' => [14, 17, 16, 23, 17, 17, 15],
         'H' => [17, 17, 17, 31, 17, 17, 17],
         'I' => [14, 4, 4, 4, 4, 4, 14],
         'J' => [7, 2, 2, 2, 18, 18, 12],
         'K' => [17, 18, 20, 24, 20, 18, 17],
         'L' => [16, 16, 16, 16, 16, 16, 31],
         'M' => [17, 27, 21, 21, 17, 17, 17],
         'N' => [17, 25, 25, 21, 19, 19, 17],
         'O' => [14, 17, 17, 17, 17, 17, 14],
         'P' => [30, 17, 17, 30, 16, 16, 16],
         'Q' => [14, 17, 17, 17, 21, 18, 13],
         'R' => [30, 17, 17, 30, 20, 18, 17],
         'S' => [15, 16, 16, 14, 1, 1, 30],
         'T' => [31, 4, 4, 4, 4, 4, 4],
         'U' => [17, 17, 17, 17, 17, 17, 14],
         'V' => [17, 17, 17, 17, 17, 10, 4],
         'W' => [17, 17, 17, 21, 21, 21, 10],
         'X' => [17, 17, 10, 4, 10, 17, 17],
         'Y' => [17, 17, 10, 4, 4, 4, 4],
         'Z' => [31, 1, 2, 4, 8, 16, 31],
         '0' => [14, 17, 19, 21, 25, 17, 14],
         '1' => [4, 12, 4, 4, 4, 4, 14],
         '2' => [14, 17, 1, 2, 4, 8, 31],
         '3' => [30, 1, 1, 14, 1, 1, 30],
         '4' => [2, 6, 10, 18, 31, 2, 2],
         '5' => [31, 16, 16, 30, 1, 1, 30],
         '6' => [14, 16, 16, 30, 17, 17, 14],
         '7' => [31, 1, 2, 4, 8, 8, 8],
         '8' => [14, 17, 17, 14, 17, 17, 14],
         '9' => [14, 17, 17, 15, 1, 1, 14],
         '-' => [0, 0, 0, 31, 0, 0, 0],
         '.' => [0, 0, 0, 0, 0, 12, 12],
         '/' => [1, 2, 2, 4, 8, 8, 16],
         ':' => [0, 12, 12, 0, 12, 12, 0],
         '_' => [0, 0, 0, 0, 0, 0, 31],
         _ => [0; 7],
     }
 }

 fn draw_pixel_text(batch: &mut HudBatch, atlas: &HudAtlas, text: &str, x: f32, y: f32, scale: f32) {
     let color = rgba(238, 241, 250, 255);
     for (index, ch) in text.chars().enumerate() {
         let rows = pixel_glyph_rows(ch);
         for (row, bits) in rows.into_iter().enumerate() {
             for col in 0..5 {
                 if bits & (1 << (4 - col)) != 0 {
                     batch.fill(
                         atlas,
                         x + (index as f32 * 6.0 + col as f32) * scale,
                         y + row as f32 * scale,
                         scale,
                         scale,
                         color,
                     );
                 }
             }
         }
     }
 }

 fn draw_resource_error(batch: &mut HudBatch, atlas: &HudAtlas) {
     let scale = (batch.height / 360.0).floor().max(1.0);
     let lines = [
         "HORIZON",
         "JAVA RESOURCES NOT FOUND",
         "PREPARE YOUR FILES ON A PC WITH",
         "HORIZON-PREPARE --PREPARE",
         "COPY THE OUTPUT INTO:",
         "ANDROID/DATA/DEV.PLAYHORIZON.HORIZON.CLIENT/FILES/RESOURCES/26.3",
         "RESTART HORIZON AFTER COPYING",
         "DETAILS ARE IN ANDROID/README.MD",
     ];
     let panel_width = batch.width * 0.9;
     let panel_height = (lines.len() as f32 * 16.0 * scale + 32.0).min(batch.height * 0.9);
     let panel_x = (batch.width - panel_width) / 2.0;
     let panel_y = (batch.height - panel_height) / 2.0;
     batch.fill(
         atlas,
         0.0,
         0.0,
         batch.width,
         batch.height,
         rgba(10, 13, 22, 255),
     );
     batch.fill(
         atlas,
         panel_x,
         panel_y,
         panel_width,
         panel_height,
         rgba(25, 31, 48, 255),
     );
     for (index, line) in lines.iter().enumerate() {
         let text_width = line.len() as f32 * 6.0 * scale;
         let x = (batch.width - text_width) / 2.0;
         let y = panel_y + 16.0 * scale + index as f32 * 16.0 * scale;
         draw_pixel_text(batch, atlas, line, x, y, scale);
     }
 }

